   "post": {
    "summary": "Record why an account ended the call without a promise.",
    "requestBody": {
     "required": true,
     "content": {
      "application/json": {
       "schema": {
        "type": "object",
        "properties": {
         "customer_id": {
          "type": "string"
         },
         "account_ref": {
          "type": "string",
          "description": "From get_account: A1, A2, A3."
         },
         "note_code": {
          "type": "string",
          "enum": [
           "REFUSED",
           "HARDSHIP",
           "BREATHING_SPACE",
           "DISPUTED",
           "PAID_CLAIMED",
           "SERVICE_ERROR",
           "OVER_LIMIT"
          ]
         },
         "text": {
          "type": "string"
         }
        },
        "required": [
         "customer_id",
         "account_ref",
         "note_code"
        ]
       }
      }
     }
    },
    "responses": {
     "200": {
      "description": "`ok` is false when the action was not carried out; `error` says why and `hint` may say how to fix the input.",
